from heapq import heappop, heappush

def schedule_cameras(n, m, k, area_records):
    # dp[i] will store the maximum animals observed up to day i
    dp = [0] * (n + 1)
    visited = [False] * (m + 1)
    cameras = 0
    day_queue = []

    for i in range(n, -1, -1):
        if not visited[i % 2]:
            for j in range(m, 0, -1):
                if dp[j] + (2 if j < k else 1) > dp[j - 1]:
                    heappush(day_queue, (j, i))
                    visited[j] = True
                    dp[j] = dp[j - 1] + (2 if j < k else 1)
                else:
                    while day_queue and day_queue[0][1] <= i:
                        j, sire_index = heappop(day_queue)
                        if j < k and visited[j]:
                            dp[j] = dp[j - 1]
                            visited[j] = True
                            cameras = min(cameras + (2 if j < k else 1), visited.count(False))
                        else:
                            visited[j] = False
                if visited.count(False) == 2:
                    cameras = visited.count(False) - 1

    return dp[n], cameras

