import math
from math import gcd

def get_divisors(n):
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if n / i == i:
                divisors.append(i)
            else:
                divisors.append(i)
                divisors.append(n / i)
    return divisors

def get_lcm(a, b):
    return a * b // gcd(a, b)

def find_tuples(a, b, n):
    if gcd(a, b) != 1:
        return 0

    n = n + (a - 1) + (b - 1)
    lcm_ab = (a + 1) * (b + 1) // gcd(a + 1, b + 1)
    max_a = (n // lcm_ab) - (a + 1) - 1
    tuples = []

    for i in range(max_a + 1):
        a_sum = (a + 1) * i - 1
        b_sum = (b + 1) * i

        if a_sum * b_sum - n + (a + 1) * (b + 1) * i <= 0:
            break

        tuples.append((a_sum, b_sum))

    ans = 0
    for i in range(a, max_a + 1):
        ans += len([t for t in tuples if t[1] == i])

    return ans

def get_possible_ways(n):
    divisors = get_divisors(n)
    tubles = 0

    for a in divisors:
        for b in divisors:
            if a != 1 and b != 1:
                for c in get_divisors(a + b):
                    tubles += find_tuples(a, b, n)

    return tubles

