from typing import List

def optimalCameraPlacement(n: int, m: int, k: int, days: List[List[int]]) -> int:
    accumulatedAnimals = [[0] * (k + 1) for _ in range(m + 1)]
    for i, animals in enumerate(days):
        for j in range(m):
            for l in range(min(k, len(animals))):
                accumulatedAnimals[j + 1][1 + (l - j) % (k - 1)] += max(0, animals[j] - (k - 1 - l) // (k - 1) / 2)

    @lru_cache(None)
    def dp(i: int, j: int) -> int:
        if i == len(days[0]):
            return 0
        if accumulatedAnimals[0][j % k] > 0:
            return dp(i + 1, 0) + accumulatedAnimals[0][j % k]
        else:
            return max(dp(i + 1, k), dp(i + 1, j + 1) + accumulatedAnimals[i][(j + 1) % k])

    return max(dp(0, 0), dp(0, 1) + accumulatedAnimals[0][k - 1])

