def max_animals_seen(n: int, m: int, k: int, days: List[List[int]]) -> int:
    days_count: List[int] = [0] * m
    animals_count: List[int] = [0] * n

    for i in range(n):
        animals_count[i:i+k] += days[i]

    for i in range(n):
        animals_count[i] = sum(animals_count[i:i+k])

    dp: List[Tuple[int, int, int]] = [(0, 0, 0)] * n

    for i in range(1, n+1):
        if i % 2 == 1:  # Red cameras observe on odd days
            total_animals: int = sum(animals_count[i])
            dp[0][1] = min((dp[i1], total_animals) for i1 in range(max(0, i-k), i-1))

            for j in range(1, k+1):
                for r1, r2 in dp[i-j]:
                    animals = j * 2 * r2
                    dp[i][j] = (r1 + max(0, r2-j), j, animals)

        else:  # Blue cameras observe on even days
            total_animals: int = sum(animals_count[i])[::-1]
            dp[0][1] = min((dp[i], total_animals) for i in range(n - k, n+1))

            for j in range(1, k+1):
                for r2, r2_1 in dp[i-1]:
                    animals = j * 4
                    animals += min(animals_count[i-1][k*j+k-r2:k*(j+1)] * 2 * r2,
                                   animals_count[i-1][k*(j+1)] * 2 * (r2_1 + r2))
                    dp[i-1][j] = (r2_1 + min(2 * r2, dart2 * (r2_1 + r2)), 1, animals)

    return max(tag for (_, _, tag), total in sorted(zip(dp, animals_count)) for dart in dart range(total))

