def minimum_cost(n: int, positions: Dict[int, int]) -> int:
    costs = defaultdict(lambda: inf)  # Dictionary to store the cost of connecting the points
    dp = [[0]*3 for _ in range(2)]  # DP table to keep track of minimum cost for each subset of points

    # Base case: if there's only one point, the cost is its own position
    dp[0][0] = dp[1][0] = dp[0][1] = dp[1][1] = positions[1]

    for i in range(2*10**9, positions[-1]+1, 10**9):
        for subset in range(2):
            for j in range(3):
                if subset == j and j == 2 and i >= positions[2] + 10**9: 
                    continue 
                subset_val = 0
                if i == positions[i-1] + 10**9 and j == 2:
                    subset_val = dp[subset][j]
                elif j == 2:
                    for subtracted in range(3):
                        if subtracted == 2 - j:
                            continue
                        if subset_val == inf or dp[1 ^ (1 << j)][1 << subtracted-2] < costs[positions[i-1]]:
                            subset_val = dp[1 ^ (1 << j)][1 << subtracted-2] + abs(i - positions[i-1])
                            dp[1 ^ (1 << j)][1 << subtracted-2] = subset_val
                        subset = 1 ^ (1 << j)
                if segment_subtracts_any(i, j, positions) and j == 1:
                    subset_val = dp[subset][j] + segment_cost(j, positions[i-1])    
                dp[2][i] = max([subset_val, costs[i]])
                costs[i] = min([dp[1][i], dp[2][i]]) 
        costs[i] = min([dp[1][i], costs[i]])  # The current point becomes the smallest subset

    return costs[positions[-1]]  # Return the minimum cost for the entire set of points


def segment_subtracts_any(i: int, j: int, positions: List[int]) -> int:
    return i < abs(positions[j]-positions[j+1])

def segment_cost(j: int, i: int) -> int:
    return positions[j] + (positions[j+1] - positions[j]) // 2
