import math

def count_ways(n):
    def calculate_orderings(a, b, c):
        # Gregory's Magic Formula - Counts permutations of sizes a:c:b
        return math.factorial(a+b+c) // (math.factorial(a) * math.factorial(b) * math.factorial(c))

    ways = 0

    while n >= 0:
        # Calculate remaining to be filled in with a new cube of side a + b + c
        units_left = n + a + b + c - (a + b + c)
        if 2*a >= c or 2*b >= c:
            if units_left >= 3*a:  
                # First case: we have 3a units left, so we try to take systems of 8 and keep changing cubes sizes...
                ways += calculate_orderings(3*a // 8 * 8, 3*a % 8 // 2, 3*a % 8 % 2)
            elif units_left >= 3*b:
                # Second case: we have 3b units left.
                # We just implant that much components in two cubes of sides (a,b), which unite up to volume of 2/3 of the manually decomposed large cube.
                ways += calculate_orderings(2*b, 3*b // 2, 3*b % 2)
        # If no more "3a" or "3b" groups of units will fit then we try "2a" but this time out of b + c respectively.
        if 2*a >= c: 
            if units_left >= a + b: 
                # Process manually decomposed 2a big cube in the frame of cube a,b - just implement in proper position, a * 2 equal parts, next - delete all other parts by number of remaining the same fall number of arrays halves per for next cycle.
                ways += calculate_orderings(2*a, a // (a-float(c)), (a + float(c)) // 2)

        n = units_left

    print(ways)

