from collections import defaultdict

def find_number_of_distinct_strings(N, S):
    MOD = 10 ** 9 + 7
    dp = defaultdict(int)

    def dfs(index, prev_char):
        if index == N:
            return 1
        if (index, prev_char) in dp:
            return dp[(index, prev_char)]

        result = 0
        for char in 'ABC' if prev_char == '.' else ['C', 'B', 'A']:
            if char != S[index] and char != S[index - 1]:
                result = (result + dfs(index + 1, char)) % MOD
        dp[(index, prev_char)] = result
        return result

    return dfs(0, '.')

