def calculate_probability(n, m, k):
    total_possible_orders = comb(n + m, n)
    favorable_orders = 0

    for order in product(range(n + m), repeat=n + m):
        ticket_checker = [0] * n + [-1] * m
        count_banknotes = k + sum(order[i] < 0 for i in range(m))

        for i in range(len(order)): 
            if ticket_checker[i]:
                continue

            if ticket_checker[i] == 0:
                count_banknotes -= 1

            ticket_checker[i] += order[i]

            if ticket_checker[i] == 0:
                if count_banknotes < len(order) - i:
                    break
                if i < m and count_banknotes == m - i:
                    favorable_orders += 1

            if count_banknotes < 0:
                break

        if count_banknotes < 0:
            break

