            self.logger.append(len(self.logger))
            return 0

        if not self.logger or self.logger[-1] != self.tasks_completed[-1]:
            return self.count_time_travels

        self.logger.append(1)
        return 0

    def count_time_travels(self):
        return sum(len(task) for task in self.previous_tasks)

def solve(n, pairs, ts):
    tracker = TaskTracker(set())
    for pair in pairs:
        a, b = pair
        tracker.update(set([a]))
        if b in tracker.tasks_completed:
            return tracker.count_time_travels

        if b in tracker.previous_tasks:
            _ = tracker.time_travel(b)

    return tracker.count_time_travels

n = int(input())
pairs = [tuple(map(int, input().split())) for _ in range(n)]
ts = list(map(int, input().split()))
