from collections import defaultdict

def reciprocal_prime(m):
    # Returns the modular inverse of m under modulo prime p
    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    _, x, _ = extended_gcd(m, p)
    return x % p

def modular_inverse(m):
    # Returns the modular inverse of m under modulo prime p
    # equivalent to the function reciprocal_prime for prime p of type 2^31 - 1
    return pow(m, p - 2, p)

prime = 998244353

modinv_1 = modular_inverse(1)

factor_set = {
