memo = defaultdict(int)

def recurse(n):
    if n == 1:
        return modinv_1 
    if n in factor_set: 
      return factor_set[n]
    if n in memo:
        return memo[n] 

    res = 0
    for i in range(n):
        temp = recurse(i) 
        for j in range(i + 1, n):
            temp *= recurse(j - i) 
            temp %= p
        res += temp 
    res %= p
    res *= recurse(n-1) 
    res %= p
    memo[n] = res
    return res

