from collections import defaultdict

def is_possible_to_split(n, m, roads):
    adjacency_matrix = [[0] * n for _ in range(n)]
    for u, v in roads:
        adjacency_matrix[u-1][v-1] = adjacency_matrix[v-1][u-1] = 1

    visited = [False] * n
    def dfs(city, path):
        if visited[city]:
            return False
        visited[city] = True
        path.append(city + 1)
        for neighbor in range(n):
            if adjacency_matrix[city][neighbor] and not dfs(neighbor, path):
                return False
        return True

    results = []
    for city in range(n):
        if dfs(city, []):
            results.append([path for path in range(n+1)])
    return results

def main():
